INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (358, 1, '프로바이더 네트워크란', '**프로바이더 네트워크** 에 대한 설명으로 알맞은 것은 무엇일까요?', '이미 있는 실제 네트워크에 이어 주는 쪽이에요.', NULL, NULL, '[]', 'choice', '["사용자가 서버 안에서 임의로 만드는 가상 키보드 설정", "서버의 이미지를 내려받는 전용 저장소를 가리키는 말", "기존 데이터센터 네트워크에 대응하는 연결로, 보통 관리자가 만든다", "서버 사용료를 계산해 알려 주는 청구 네트워크"]', 2, '공식 문서는 프로바이더 네트워크가 인스턴스에 2계층 연결을 제공하며 기존 데이터센터 네트워크(보통 VLAN)에 대응하고, 기본적으로 관리자만 만들 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (358, 2, '셀프서비스 네트워크란', '**셀프서비스 네트워크** 에 대한 설명으로 알맞은 것은 무엇일까요?', '이름처럼 사용자가 스스로 만드는 쪽이에요.', NULL, NULL, '[]', 'choice', '["관리자만 만들 수 있고 일반 프로젝트는 볼 수 없는 네트워크", "일반 프로젝트가 관리자 도움 없이 직접 만들고 관리하는 가상 네트워크", "서버가 없어도 항상 모든 프로젝트와 공유되는 네트워크", "물리 스위치에 케이블로만 연결해서 쓰는 네트워크"]', 1, '셀프서비스 네트워크는 일반(비특권) 프로젝트가 관리자 개입 없이 네트워크를 관리하게 해 주는 가상 네트워크이고, 보통 VXLAN 같은 오버레이 프로토콜을 씁니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (358, 3, '두 네트워크의 만드는 주체', '프로바이더 네트워크와 셀프서비스 네트워크를 **누가 만드는지** 로 구분하면 알맞은 것은 무엇일까요?', '한쪽은 관리자, 한쪽은 프로젝트예요.', NULL, NULL, '[]', 'choice', '["프로바이더는 보통 관리자가, 셀프서비스는 프로젝트 사용자가 만든다", "프로바이더는 서버가, 셀프서비스는 하이퍼바이저가 만든다", "둘 다 일반 사용자는 만들 수 없다", "프로바이더는 사용자가, 셀프서비스는 관리자만 만든다"]', 0, '프로바이더 네트워크는 기존 데이터센터 네트워크에 대응해서 기본적으로 관리자만 만들 수 있고, 셀프서비스 네트워크는 일반 프로젝트가 직접 관리합니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (358, 4, '보안 그룹이란', 'Neutron 의 **보안 그룹** 은 무엇일까요?', '출입 규칙을 모아 둔 목록이에요.', NULL, NULL, '[]', 'choice', '["서버끼리 서로 이름을 부르는 데 쓰는 별명 목록 모음", "서버가 쓸 수 있는 디스크와 메모리의 최대 한도 표", "서버를 사용할 수 있는 사람들의 명단과 권한 표 모음", "들어오고 나가는 트래픽을 제어하는 가상 방화벽 규칙의 모음"]', 3, '공식 문서는 보안 그룹을 인스턴스로 들어오는(ingress) 트래픽과 나가는(egress) 트래픽을 제어하는 가상 방화벽 규칙의 컨테이너라고 설명합니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (358, 5, '보안 그룹이 적용되는 곳', '보안 그룹의 규칙은 어디에 적용될까요?', '서버가 네트워크에 연결된 지점이에요.', NULL, NULL, '[]', 'choice', '["프로젝트에 있는 모든 서버에 한꺼번에 항상 똑같이", "서버의 디스크 볼륨 한 개마다", "서버의 포트 단위", "물리 서버의 전원 장치마다"]', 2, '공식 문서에 따르면 보안 그룹은 포트 단위로 적용되고, 기본적으로 허용하지 않는(deny by default) 방식입니다. 허용 규칙을 추가한 만큼만 트래픽이 통과합니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (358, 6, '규칙을 추가하지 않으면', '보안 그룹이 **기본적으로 거부(deny by default)** 방식입니다. 새 서버에 SSH 허용 규칙을 추가하지 않으면 어떻게 될까요?', '허용한 것만 통과해요.', NULL, NULL, '[]', 'choice', '["SSH 접속이 항상 자동으로 허용된다", "밖에서 들어오는 SSH 접속은 허용되지 않는다", "서버가 만들어지지 않고 ERROR 상태가 된다", "서버가 SSH 대신 다른 접속 방법을 자동으로 연다"]', 1, '보안 그룹은 허용 규칙을 추가한 트래픽만 통과시킵니다. 인스턴스 만들기 문서도 기본 보안 그룹은 규칙을 바꾸지 않으면 클라우드 밖에서의 접근을 허용하지 않는다고 안내합니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (358, 7, '플로팅 IP 의 역할', '**플로팅 IP** 는 어떤 일을 할까요?', '밖에서 서버를 찾아올 수 있게 해 주는 주소예요.', NULL, NULL, '[]', 'choice', '["라우터의 목적지 NAT 로 밖에서 인스턴스에 접근하게 해 준다", "서버의 CPU 사용량을 자동으로 줄여서 비용을 아껴 준다", "서버가 만들어질 때 쓰는 디스크 이미지를 바꿔 준다", "서버끼리의 모든 통신을 자동으로 암호화해서 보호해 준다"]', 0, '공식 문서는 플로팅 IP 가 가상 라우터의 목적지 NAT 를 통해 프로바이더 네트워크에서 인스턴스에 접근할 수 있게 한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (358, 8, '플로팅 IP 만으로 충분할까', '서버에 플로팅 IP 를 붙였는데도 밖에서 SSH 가 안 됩니다. 이유로 가장 알맞은 것은 무엇일까요?', '문을 찾아왔어도 열어 줘야 들어가요.', NULL, NULL, '[]', 'choice', '["플로팅 IP 는 붙이면 보안 그룹이 자동으로 꺼진다", "서버의 이름에 숫자가 들어 있어서 막힌다", "플로팅 IP 는 SSH 에는 쓸 수 없다고 정해져 있다", "보안 그룹이 그 트래픽을 허용하지 않아서일 수 있다"]', 3, '플로팅 IP 는 접근 경로를 열어 줄 뿐이고, 들어오는 트래픽은 보안 그룹 규칙으로 따로 허용되어야 합니다. 보안 그룹은 기본적으로 거부이므로 허용 규칙이 있는지 확인합니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (358, 9, 'DHCP 가 하는 일', 'Neutron 의 선택적 **DHCP** 서비스는 무엇을 할까요?', '서버가 주소를 스스로 받아 오게 해 줘요.', NULL, NULL, '[]', 'choice', '["인스턴스의 디스크 암호를 자동으로 바꿔 준다", "인스턴스가 만든 파일을 다른 서버로 복사해 준다", "인스턴스의 IP 주소를 관리해 나눠 준다", "인스턴스의 CPU 온도를 모니터링해 알려 준다"]', 2, '공식 문서는 DHCP 서비스를 프로바이더 네트워크와 셀프서비스 네트워크의 인스턴스 IP 주소를 관리하는 선택적 서비스라고 설명합니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (358, 10, 'SSH 허용 규칙 만들기', '기본 보안 그룹에 **SSH 접속을 허용** 하려고 합니다. 빈칸의 포트 번호를 채우세요.', 'SSH 의 기본 포트예요.', NULL, NULL, '[]', 'fill', '["22", "80", "3306", "5432"]', NULL, 'SSH 의 기본 포트는 22 번입니다. 80 은 HTTP, 3306 은 MySQL·MariaDB, 5432 는 PostgreSQL 의 기본 포트입니다.', '[0]', 'openstack security group rule create --protocol tcp --dst-port {0} default', NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (358, 11, '플로팅 IP 만들기', '외부 네트워크 `ext-net` 에서 **플로팅 IP** 를 하나 만드는 명령입니다. 빈칸을 채우세요.', '떠다니는 주소라는 이름 그대로예요.', NULL, NULL, '[]', 'fill', '["floating", "static", "fixed", "elastic"]', NULL, '`openstack floating ip create` 로 외부 네트워크에서 플로팅 IP 를 하나 받습니다. 받은 뒤 서버에 연결해야 접근할 수 있습니다.', '[0]', 'openstack {0} ip create ext-net', NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (358, 12, '밖에서 서버에 SSH 로 들어가기까지', '외부에서 서버에 SSH 로 접속할 수 있게 열어 주는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '규칙 → 주소 → 연결 → 접속 순서예요.', NULL, NULL, '[]', 'order', '["보안 그룹에 SSH(22번 포트) 허용 규칙을 추가한다", "플로팅 IP 를 하나 만든다", "그 플로팅 IP 를 서버에 연결한다", "키로 SSH 접속해 본다"]', NULL, '들어오는 SSH 를 허용하는 규칙을 먼저 두고, 밖에서 찾아올 플로팅 IP 를 만들어 서버에 연결한 뒤 접속합니다. 환경에 따라 이미 연결된 경우도 있습니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]');
